import{_ as t,a0 as r,w as o,s as b,I as p,x as s,a1 as e,A as l,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"熱愛你的 Bug | LCTT x X-CMD","titleTemplate":false,"description":"熱愛你的 Bug | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"熱愛你的 Bug | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"熱愛你的 Bug | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171112 Love Your Bugs","title":"熱愛你的 Bug","tag":"201801","desc":""},"relativePath":"201801/20171112 Love Your Bugs.md","filePath":"[post].md"}'),u={name:"201801/20171112 Love Your Bugs.md"};function g(d,a,h,k,c,f){const n=r("Link");return o(),b("div",null,[a[31]||(a[31]=p("h1",{id:"熱愛你的-bug",tabindex:"-1"},[s("熱愛你的 Bug "),p("a",{class:"header-anchor",href:"#熱愛你的-bug","aria-label":"Permalink to “熱愛你的 Bug”"},"​")],-1)),p("p",null,[a[2]||(a[2]=s("十月初的時候我在貝洛奧裏藏特的",-1)),e(n,{href:"http://2017.pythonbrasil.org.br/#"},{default:l(()=>[...a[0]||(a[0]=[p("ruby",null,[s("巴西 Python 大會"),p("rt",null,"Python Brasil")],-1)])]),_:1}),a[3]||(a[3]=s("上做了主題演講。這是稍加改動過的演講文稿。你可以在",-1)),e(n,{href:"http://www.youtube.com/watch?v=h4pZZOmv4Qs"},{default:l(()=>[...a[1]||(a[1]=[s("這裏",-1)])]),_:1}),a[4]||(a[4]=s("觀看演講視頻。",-1))]),a[32]||(a[32]=p("h3",{id:"我愛-bug",tabindex:"-1"},[s("我愛 bug "),p("a",{class:"header-anchor",href:"#我愛-bug","aria-label":"Permalink to “我愛 bug”"},"​")],-1)),p("p",null,[a[8]||(a[8]=s("我目前是 ",-1)),e(n,{href:"http://www.pilot.com/"},{default:l(()=>[...a[5]||(a[5]=[s("Pilot.com",-1)])]),_:1}),a[9]||(a[9]=s(" 的一位高級工程師，負責給創業公司提供自動記賬服務。在此之前，我曾是 ",-1)),e(n,{href:"http://www.dropbox.com/"},{default:l(()=>[...a[6]||(a[6]=[s("Dropbox",-1)])]),_:1}),a[10]||(a[10]=s(" 的桌面客户端組的成員，我今天將分享關於我當時工作的一些故事。更早之前，我是 ",-1)),e(n,{href:"http://www.recurse.com/"},{default:l(()=>[...a[7]||(a[7]=[s("Recurse Center",-1)])]),_:1}),a[11]||(a[11]=s(" 的導師，給身在紐約的程序員提供臨時的訓練環境。在成為工程師之前，我在大學攻讀天體物理學並在金融界工作過幾年。",-1))]),a[33]||(a[33]=i(`<p>但這些都不重要——關於我你唯一需要知道的是，我愛 bug。我愛 bug 因為它們有趣。它們富有戲劇性。調試一個好的 bug 的過程可以非常迂迴曲折。一個好的 bug 像是一個有趣的笑話或者或者謎語——你期望看到某種結果，但卻事與願違。</p><p>在這個演講中我會給你們講一些我曾經熱愛過的 bug，解釋為什麼我如此愛 bug，然後説服你們也同樣去熱愛 bug。</p><h3 id="bug-1-號" tabindex="-1">Bug 1 號 <a class="header-anchor" href="#bug-1-號" aria-label="Permalink to “Bug 1 號”">​</a></h3><p>好，讓我們直接來看第一個 bug。這是我在 Dropbox 工作時遇到的一個 bug。你們或許聽説過，Dropbox 是一個將你的文件從一個電腦上同步到雲端和其他電腦上的應用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>        +--------------+     +---------------+</span></span>
<span class="line"><span>        |              |     |               |</span></span>
<span class="line"><span>        |  元數據服務器  |     |     塊服務器    |</span></span>
<span class="line"><span>        |              |     |               |</span></span>
<span class="line"><span>        +-+--+---------+     +---------+-----+</span></span>
<span class="line"><span>          ^  |                         ^</span></span>
<span class="line"><span>          |  |                         |</span></span>
<span class="line"><span>          |  |     +----------+        |</span></span>
<span class="line"><span>          |  +---&gt; |          |        |</span></span>
<span class="line"><span>          |       |   客户端   +--------+</span></span>
<span class="line"><span>          +--------+          |</span></span>
<span class="line"><span>                   +----------+</span></span></code></pre></div><p>這是個極度簡化的 Dropbox 架構圖。桌面客户端在你的電腦本地運行，監聽文件系統的變動。當它檢測到文件改動時，它讀取改變的文件，並把它的內容 hash 成 4 MB 大小的文件塊。這些文件塊被存放在後端一個叫做<ruby>塊服務器<rt>blockserver</rt></ruby>的巨大的<ruby>鍵值對資料庫<rt>key-value store</rt></ruby>中。</p><p>當然，我們想避免多次上傳同一個文件塊。可以想見，如果你在編寫一份文檔，你應該大部分時候都在改動文檔最底部——我們不想一遍又一遍地上傳開頭部分。所以在上傳文件塊到塊服務器之前之前，客户端會先和一個負責管理元數據和權限等等的服務器溝通。客户端會詢問這個<ruby>元數據服務器<rt>metaserver</rt></ruby>它是需要這個文件塊，還是已經見過這個文件塊了。元數據服務器會返回每一個文件塊是否需要上傳。</p><p>所以這些請求和響應看上去大概是這樣：客户端説“我有一個改動過的文件，分為這些文件塊，它們的 hash 是 <code>&#39;abcd,deef,efgh&#39;</code>。服務器響應説“我有前兩塊，但需要你上傳第三塊”。然後客户端會把那個文件塊上傳到塊服務器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                +--------------+     +---------------+</span></span>
<span class="line"><span>                |              |     |               |</span></span>
<span class="line"><span>                |  元數據服務器  |     |     塊服務器    |</span></span>
<span class="line"><span>                |              |     |               |</span></span>
<span class="line"><span>                +-+--+---------+     +---------+-----+</span></span>
<span class="line"><span>                  ^  |                         ^</span></span>
<span class="line"><span>                  |  | &#39;有, 有, 無&#39;             |</span></span>
<span class="line"><span>&#39;abcd,deef,efgh&#39;  |  |     +----------+        | efgh: [內容]</span></span>
<span class="line"><span>                  |  +---&gt; |          |        |</span></span>
<span class="line"><span>                  |        |   客户端   +--------+</span></span>
<span class="line"><span>                  +--------+          |</span></span>
<span class="line"><span>                           +----------+</span></span></code></pre></div><p>這是問題的背景。下面是 bug。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                +--------------+</span></span>
<span class="line"><span>                |              |</span></span>
<span class="line"><span>                |    塊服務器    |</span></span>
<span class="line"><span>                |              |</span></span>
<span class="line"><span>                +-+--+---------+</span></span>
<span class="line"><span>                  ^  |</span></span>
<span class="line"><span>                  |  |   &#39;???&#39;</span></span>
<span class="line"><span>&#39;abcdldeef,efgh&#39;  |  |     +----------+</span></span>
<span class="line"><span>     ^            |  +---&gt; |          |</span></span>
<span class="line"><span>     ^            |        |   客户端  +</span></span>
<span class="line"><span>                  +--------+          |</span></span>
<span class="line"><span>                           +----------+</span></span></code></pre></div><p>有時候客户端會提交一個奇怪的請求：每個 hash 值應該包含 16 個字母，但它卻發送了 33 個字母——所需數量的兩倍加一。服務器不知道該怎麼處理它，於是會拋出一個異常。我們收到這個異常的報告，於是去查看客户端的記錄文件，然後會看到非常奇怪的事情——客户端的本地資料庫損壞了，或者 python 拋出 MemoryError，沒有一個合乎情理的。</p><p>如果你以前沒見過這個問題，可能會覺得毫無頭緒。但當你見過一次之後，你以後每次看到都能輕鬆地認出它來。給你一個提示：在那些 33 個字母的字符串中，<code>l</code> 經常會代替逗號出現。其他經常出現的字符是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>l \\x0c &lt; $ ( . -</span></span></code></pre></div><p>英文逗號的 ASCII 碼是 44。<code>l</code> 的 ASCII 碼是 108。它們的二進制表示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bin(ord(&#39;,&#39;)): 0101100  </span></span>
<span class="line"><span>bin(ord(&#39;l&#39;)): 1101100</span></span></code></pre></div><p>你會注意到 <code>l</code> 和逗號只差了一位。問題就出在這裏：發生了位反轉。桌面客户端使用的內存中的一位發生了錯誤，於是客户端開始向服務器發送錯誤的請求。</p><p>這是其他經常代替逗號出現的字符的 ASCII 碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>,    : 0101100</span></span>
<span class="line"><span>l    : 1101100</span></span>
<span class="line"><span>\\x0c : 0001100</span></span>
<span class="line"><span>&lt;    : 0111100</span></span>
<span class="line"><span>$    : 0100100</span></span>
<span class="line"><span>(    : 0101000</span></span>
<span class="line"><span>.    : 0101110</span></span>
<span class="line"><span>-    : 0101101</span></span></code></pre></div><h4 id="位反轉是真的" tabindex="-1">位反轉是真的！ <a class="header-anchor" href="#位反轉是真的" aria-label="Permalink to “位反轉是真的！”">​</a></h4><p>我愛這個 bug 因為它證明了位反轉是可能真實發生的事情，而不只是一個理論上的問題。實際上，它在某些情況下會比平時更容易發生。其中一種情況是用户使用的是低配或者老舊的硬件，而運行 Dropbox 的電腦很多都是這樣。另外一種會造成很多位反轉的地方是外太空——在太空中沒有大氣層來保護你的內存不受高能粒子和輻射的影響，所以位反轉會十分常見。</p>`,21)),p("p",null,[a[13]||(a[13]=s("你大概非常在乎在宇宙中運行的程序的正確性——你的代碼或許事關國際空間站中宇航員的性命，但即使沒有那麼重要，也還要考慮到在宇宙中很難進行軟件更新。如果你的確需要讓你的程序能夠處理位反轉，有很多硬件和軟件措施可供你選擇，Katie Betchold 還關於這個問題做過一個",-1)),e(n,{href:"http://www.youtube.com/watch?v=ETgNLF_XpEM"},{default:l(()=>[...a[12]||(a[12]=[s("非常有意思的講座",-1)])]),_:1}),a[14]||(a[14]=s("。",-1))]),a[34]||(a[34]=i(`<p>在剛才那種情況下，Dropbox 並不需要處理位反轉。出現內存損壞的是用户的電腦，所以即使我們可以檢測到逗號字符的位反轉，但如果這發生在其他字符上我們就不一定能檢測到了，而且如果從硬盤中讀取的文件本身發生了位反轉，那我們根本無從得知。我們能改進的地方很少，於是我們決定無視這個異常並繼續程序的運行。這種 bug 一般都會在客户端重啓之後自動解決。</p><h4 id="不常見的-bug-並非不可能發生" tabindex="-1">不常見的 bug 並非不可能發生 <a class="header-anchor" href="#不常見的-bug-並非不可能發生" aria-label="Permalink to “不常見的 bug 並非不可能發生”">​</a></h4><p>這是我最喜歡的 bug 之一，有幾個原因。第一，它提醒我注意不常見和不可能之間的區別。當規模足夠大的時候，不常見的現象會以值得注意的頻率發生。</p><h4 id="覆蓋面廣的-bug" tabindex="-1">覆蓋面廣的 bug <a class="header-anchor" href="#覆蓋面廣的-bug" aria-label="Permalink to “覆蓋面廣的 bug”">​</a></h4><p>這個 bug 第二個讓我喜歡的地方是它覆蓋面非常廣。每當桌面客户端和服務器交流的時候，這個 bug 都可能悄然出現，而這可能會發生在系統裏很多不同的端點和組件當中。這意味着許多不同的 Dropbox 工程師會看到這個 bug 的各種版本。你第一次看到它的時候，你 <em>真的</em> 會滿頭霧水，但在那之後診斷這個 bug 就變得很容易了，而調查過程也非常簡短：你只需找到中間的字母，看它是不是個 <code>l</code>。</p><h4 id="文化差異" tabindex="-1">文化差異 <a class="header-anchor" href="#文化差異" aria-label="Permalink to “文化差異”">​</a></h4><p>這個 bug 的一個有趣的副作用是它展示了服務器組和客户端組之間的文化差異。有時候這個 bug 會被服務器組的成員發現並展開調查。如果你的 <em>服務器</em> 上發生了位反轉，那應該不是個偶然——這很可能是內存損壞，你需要找到受影響的主機並儘快把它從集羣中移除，不然就會有損壞大量用户數據的風險。這是個事故，而你必須迅速做出反應。但如果是用户的電腦在破壞數據，你並沒有什麼可以做的。</p><h4 id="分享你的-bug" tabindex="-1">分享你的 bug <a class="header-anchor" href="#分享你的-bug" aria-label="Permalink to “分享你的 bug”">​</a></h4><p>如果你在調試一個難搞的 bug，特別是在大型系統中，不要忘記跟別人討論。也許你的同事以前就遇到過類似的 bug。若是如此，你可能會節省很多時間。就算他們沒有見過，也不要忘記在你解決了問題之後告訴他們解決方法——寫下來或者在組會中分享。這樣下次你們組遇到類似的問題時，你們都會早有準備。</p><h3 id="bug-如何幫助你進步" tabindex="-1">Bug 如何幫助你進步 <a class="header-anchor" href="#bug-如何幫助你進步" aria-label="Permalink to “Bug 如何幫助你進步”">​</a></h3><h4 id="recurse-center" tabindex="-1">Recurse Center <a class="header-anchor" href="#recurse-center" aria-label="Permalink to “Recurse Center”">​</a></h4><p>在加入 Dropbox 之前，我曾在 Recurse Center 工作。它的理念是建立一個社區讓正在自學的程序員們聚到一起來提高能力。這就是 Recurse Center 的全部了：我們沒有大綱、作業、截止日期等等。唯一的前提條件是我們都想要成為更好的程序員。參與者中有的人有計算機學位但對自己的實際編程能力不夠自信，有的人已經寫了十年 Java 但想學 Clojure 或者 Haskell，還有各式各樣有着其他的背景的參與者。</p><p>我在那裏是一位導師，幫助人們更好地利用這個自由的環境，並參考我們從以前的參與者那裏學到的東西來提供指導。所以我的同事們和我本人都非常熱衷於尋找對成年自學者最有幫助的學習方法。</p><h4 id="刻意練習" tabindex="-1">刻意練習 <a class="header-anchor" href="#刻意練習" aria-label="Permalink to “刻意練習”">​</a></h4><p>在學習方法這個領域有很多不同的研究，其中我覺得最有意思的研究之一是刻意練習的概念。刻意練習理論意在解釋專業人士和業餘愛好者的表現的差距。它的基本思想是如果你只看內在的特徵——不論先天與否——它們都無法非常好地解釋這種差距。於是研究者們，包括最初的 Ericsson、Krampe 和 Tesch-Romer，開始尋找能夠解釋這種差距的理論。他們最終的答案是在刻意練習上所花的時間。</p><p>他們給刻意練習的定義非常精確：不是為了收入而工作，也不是為了樂趣而玩耍。你必須儘自己能力的極限，去做一個和你的水平相稱的任務（不能太簡單導致你學不到東西，也不能太難導致你無法取得任何進展）。你還需要獲得即時的反饋，知道自己是否做得正確。</p><p>這非常令人興奮，因為這是一套能夠用來建立專業技能的系統。但難點在於對於程序員來説這些建議非常難以實施。你很難知道你是否處在自己能力的極限。也很少有即時的反饋幫助你改進——有時候你能得到任何反饋都已經算是很幸運了，還有時候你需要等幾個月才能得到反饋。對於在 REPL 中做的簡單的事情你可以很快地得到反饋，但如果你在做一個設計上的決定或者技術上的選擇，你在很長一段時間裏都無法得到反饋。</p><p>但是在有一類編程工作中刻意練習是非常有用的，它就是 debug。如果你寫了一份代碼，那麼當時你是理解這份代碼是如何工作的。但你的代碼有 bug，所以你的理解並不完全正確。根據定義來説，你正處在你理解能力的極限上——這很好！你馬上要學到新東西了。如果你可以重現這個 bug，那麼這是個寶貴的機會，你可以獲得即時的反饋，知道自己的修改是否正確。</p><p>像這樣的 bug 也許能讓你學到關於你的程序的一些小知識，但你也可能會學到一些關於運行你的代碼的系統的一些更復雜的知識。我接下來要講一個關於這種 bug 的故事。</p><h3 id="bug-2-號" tabindex="-1">Bug 2 號 <a class="header-anchor" href="#bug-2-號" aria-label="Permalink to “Bug 2 號”">​</a></h3><p>這也是我在 Dropbox 工作時遇到的 bug。當時我正在調查為什麼有些桌面客户端沒有像我們預期的那樣持續發送日誌。我開始調查客户端的日誌系統並且發現了很多有意思的 bug。我會挑一些跟這個故事有關的 bug 來講。</p><p>和之前一樣，這是一個非常簡化的系統架構。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                                   +--------------+</span></span>
<span class="line"><span>                                   |              |</span></span>
<span class="line"><span>               +---+  +----------&gt; |   日誌服務器   |</span></span>
<span class="line"><span>               |日誌|  |            |              |</span></span>
<span class="line"><span>               +---+  |            +------+-------+</span></span>
<span class="line"><span>                      |                   |</span></span>
<span class="line"><span>                +-----+----+              |  200 ok</span></span>
<span class="line"><span>                |          |              |</span></span>
<span class="line"><span>                |  客户端   |  &lt;-----------+</span></span>
<span class="line"><span>                |          |</span></span>
<span class="line"><span>                +-----+----+</span></span>
<span class="line"><span>                      ^</span></span>
<span class="line"><span>                      +--------+--------+--------+</span></span>
<span class="line"><span>                      |        ^        ^        |</span></span>
<span class="line"><span>                   +--+--+  +--+--+  +--+--+  +--+--+</span></span>
<span class="line"><span>                   | 日誌 |  | 日誌 |  | 日誌 |  | 日誌 |</span></span>
<span class="line"><span>                   |     |  |     |  |     |  |     |</span></span>
<span class="line"><span>                   |     |  |     |  |     |  |     |</span></span>
<span class="line"><span>                   +-----+  +-----+  +-----+  +-----+</span></span></code></pre></div><p>桌面客户端會生成日誌。這些日誌會被壓縮、加密並寫入硬盤。然後客户端會間歇性地把它們發送給服務器。客户端從硬盤讀取日誌併發送給日誌服務器。服務器會將它解碼並存儲，然後返回 200。</p><p>如果客户端無法連接到日誌服務器，它不會讓日誌目錄無限地增長。超過一定大小之後，它會開始刪除日誌來讓目錄大小不超過一個最大值。</p><p>最初的兩個 bug 本身並不嚴重。第一個 bug 是桌面客户端向服務器發送日誌時會從最早的日誌而不是最新的日誌開始。這並不是很好——比如服務器會在客户端報告異常的時候讓客户端發送日誌，所以你可能最在乎的是剛剛生成的日誌而不是在硬盤上的最早的日誌。</p><p>第二個 bug 和第一個相似：如果日誌目錄的大小達到了上限，客户端會從最新的日誌而不是最早的日誌開始刪除。同理，你總是會丟失一些日誌文件，但你大概更不在乎那些較早的日誌。</p><p>第三個 bug 和加密有關。有時服務器會無法對一個日誌文件解碼（我們一般不知道為什麼——也許發生了位反轉）。我們在後端沒有正確地處理這個錯誤，而服務器會返回 500。客户端看到 500 之後會做合理的反應：它會認為服務器停機了。所以它會停止發送日誌文件並且不再嘗試發送其他的日誌。</p><p>對於一個損壞的日誌文件返回 500 顯然不是正確的行為。你可以考慮返回 400，因為問題出在客户端的請求上。但客户端同樣無法修復這個問題——如果日誌文件現在無法解碼，我們後也永遠無法將它解碼。客户端正確的做法是直接刪除日誌文件然後繼續運行。實際上，這正是客户端在成功上傳日誌文件並從服務器收到 200 的響應時的默認行為。所以我們説，好——如果日誌文件無法解碼，就返回 200。</p><p>所有這些 bug 都很容易修復。前兩個 bug 出在客户端上，所以我們在 alpha 版本修復了它們，但大部分的客户端還沒有獲得這些改動。我們在服務器代碼中修復了第三個 bug 並部署了新版的服務器。</p><h4 id="激增" tabindex="-1">激增 <a class="header-anchor" href="#激增" aria-label="Permalink to “激增”">​</a></h4><p>突然日誌服務器集羣的流量開始激增。客服團隊找到我們並問我們是否知道原因。我花了點時間把所有的部分拼到一起。</p><p>在修復之前，這四件事情會發生：</p><ol><li>日誌文件從最早的開始發送</li><li>日誌文件從最新的開始刪除</li><li>如果服務器無法解碼日誌文件，它會返回 500</li><li>如果客户端收到 500，它會停止發送日誌</li></ol><p>一個存有損壞的日誌文件的客户端會試着發送這個文件，服務器會返回 500，客户端會放棄發送日誌。在下一次運行時，它會嘗試再次發送同樣的文件，再次失敗，並再次放棄。最終日誌目錄會被填滿，然後客户端會開始刪除最新的日誌文件，而把損壞的文件繼續保留在硬盤上。</p><p>這三個 bug 導致的結果是：如果客户端在任何時候生成了損壞的日誌文件，我們就再也不會收到那個客户端的日誌了。</p><p>問題是，處於這種狀態的客户端比我們想像的要多很多。任何有一個損壞文件的客户端都會像被關在堤壩裏一樣，無法再發送日誌。現在這個堤壩被清除了，所有這些客户端都開始發送它們的日誌目錄的剩餘內容。</p><h4 id="我們的選擇" tabindex="-1">我們的選擇 <a class="header-anchor" href="#我們的選擇" aria-label="Permalink to “我們的選擇”">​</a></h4><p>好的，現在文件從世界各地的電腦如洪水般湧來。我們能做什麼？（當你在一個有 Dropbox 這種規模，尤其是這種桌面客户端的規模的公司工作時，會遇到這種有趣的事情：你可以非常輕易地對自己造成 DDoS 攻擊）。</p><p>當你部署的新版本發生問題時，第一個選項是回滾。這是非常合理的選擇，但對於這個問題，它無法幫助我們。我們改變的不是服務器的狀態而是客户端的——我們刪除了那些出錯文件。將服務器回滾可以防止更多客户端進入這種狀態，但它並不能解決根本問題。</p><p>那擴大日誌集羣的規模呢？我們試過了——然後因為處理能力增加了，我們開始收到更多的請求。我們又擴大了一次，但你不可能一直這麼下去。為什麼不能？因為這個集羣並不是獨立的。它會向另一個集羣發送請求，在這裏是為了處理異常。如果你的一個集羣正在被 DDoS，而你持續擴大那個集羣，你最終會把它依賴的集羣也弄壞，然後你就有兩個問題了。</p><p>我們考慮過的另一個選擇是減低負載——你不需要每一個日誌文件，所以我們可以直接無視一些請求。一個難點是我們並沒有一個很好的方法來區分好的請求和壞的請求。我們無法快速地判斷哪些日誌文件是舊的，哪些是新的。</p><p>我們最終使用的是一個 Dropbox 裏許多不同場合都用過的一個解決方法：我們有一個自定義的頭字段，<code>chillout</code>，全世界所有的客户端都遵守它。如果客户端收到一個有這個頭字段的響應，它將在字段所標註的時間內不再發送任何請求。很早以前一個英明的程序員把它加到了 Dropbox 客户端裏，在之後這些年中它已經不止一次地起了作用。</p><h4 id="瞭解你的系統" tabindex="-1">瞭解你的系統 <a class="header-anchor" href="#瞭解你的系統" aria-label="Permalink to “瞭解你的系統”">​</a></h4><p>這個 bug 的第一個教訓是要了解你的系統。我對於客户端和服務器之間的交互有不錯的理解，但我並沒有考慮到當服務器和所有這些客户端同時交互的時候會發生什麼。這是一個我沒有完全搞懂的層面。</p><h4 id="瞭解你的工具" tabindex="-1">瞭解你的工具 <a class="header-anchor" href="#瞭解你的工具" aria-label="Permalink to “瞭解你的工具”">​</a></h4><p>第二個教訓是要了解你的工具。如果出了差錯，你有哪些選項？你能撤銷你做的遷移嗎？你如何知道事情出了差錯，你又如何發現更多信息？所有這些事情都應該在危機發生之前就瞭解好——但如果你沒有，你會在危機發生時學到它們並不會再忘記。</p><h4 id="功能開關-服務器端功能控制" tabindex="-1">功能開關 &amp; 服務器端功能控制 <a class="header-anchor" href="#功能開關-服務器端功能控制" aria-label="Permalink to “功能開關 &amp; 服務器端功能控制”">​</a></h4><p>第三個教訓是專門針對移動端和桌面應用開發者的：<em>你需要服務器端功能控制和功能開關</em>。當你發現一個問題時如果你沒有服務器端的功能控制，你可能需要幾天或幾星期來推送新版本或者提交新版本到應用商店中，然後問題才能得到解決。這是個很糟糕的處境。Dropbox 桌面客户端不需要經過應用商店的審查過程，但光是把一個版本推送給上千萬的用户就已經要花很多時間。相比之下，如果你能在新功能遇到問題的時候在服務器上翻轉一個開關：十分鐘之後你的問題就已經解決了。</p><p>這個策略也有它的代價。加入很多的功能開關會大幅提高你的代碼的複雜度。而你的測試代碼更是會成指數地複雜化：要考慮 A 功能和 B 功能都開啓，或者僅開啓一個，或者都不開啓的情況——然後每個功能都要相乘一遍。讓工程師們在事後清理他們的功能開關是一件很難的事情（我自己也有這個毛病）。另外，桌面客户端會同時有好幾個版本有人使用，也會加大思考難度。</p><p>但是它的好處——啊，當你需要它的時候，你真的是很需要它。</p><h3 id="如何去愛-bug" tabindex="-1">如何去愛 bug <a class="header-anchor" href="#如何去愛-bug" aria-label="Permalink to “如何去愛 bug”">​</a></h3><p>我講了幾個我愛的 bug，也講了為什麼要愛 bug。現在我想告訴你如何去愛 bug。如果你現在還不愛 bug，我知道唯一一種改變的方法，那就是要有成長型心態。</p><p>社會學家 Carol Dweck 做了很多關於人們如何看待智力的研究。她找到兩種不同的看待智力的心態。第一種，她叫做固定型心態，認為智力是一個固定的特徵，人類無法改變自己智力的多寡。另一種心態叫做成長型心態。在成長型心態下，人們相信智力是可變的而且可以通過努力來增強。</p><p>Dweck 發現一個人看待智力的方式——固定型還是成長型心態——可以很大程度地影響他們選擇任務的方式、面對挑戰的反應、認知能力、甚至是他們的誠信度。</p>`,55)),p("p",null,[a[16]||(a[16]=s("【我在新西蘭 Kiwi Pycon 會議所做的主題演講中也討論過成長型心態，所以在此只摘錄一部分內容。你可以在",-1)),e(n,{href:"http://akaptur.com/blog/2015/10/10/effective-learning-strategies-for-programmers/"},{default:l(()=>[...a[15]||(a[15]=[s("這裏",-1)])]),_:1}),a[17]||(a[17]=s("找到完整版的演講稿】",-1))]),a[35]||(a[35]=i('<p>關於誠信的發現：</p><blockquote><p>在這之後，他們讓學生們給筆友寫信講這個實驗，信中説“我們在學校做了這個實驗，這是我得的分數”。他們發現 <em>因智力而受到表揚的學生中幾乎一半人謊報了自己的分數</em> ，而因努力而受表揚的學生則幾乎沒有人不誠實。</p></blockquote><p>關於努力：</p><blockquote><p>數個研究發現有着固定型心態的人會不願真正去努力，因為他們認為這意味着他們不擅長做他們正努力去做的這件事情。Dweck 寫道，“如果每當一個任務需要努力的時候你就會懷疑自己的智力，那麼你會很難對自己的能力保持自信。”</p></blockquote><p>關於面對困惑：</p><blockquote><p>他們發現有成長型心態的學生大約能理解 70% 的內容，不論裏面是否有難懂的段落。在有固定型心態的學生中，那些被分配沒有難懂段落的手冊的學生同樣可以理解大約 70%。但那些看到了難懂段落的持固定型心態的學生的記憶則降到了 30%。有着固定型心態的學生非常不擅長從困惑中恢復。</p></blockquote><p>這些發現表明成長型心態對 debug 至關重要。我們必須從從困惑中重整旗鼓，誠實地面對我們理解上的不足，並時不時地在尋找答案的路上努力奮鬥——成長型心態會讓這些都變得更簡單而且不那麼痛苦。</p><h4 id="熱愛你的-bug-1" tabindex="-1">熱愛你的 bug <a class="header-anchor" href="#熱愛你的-bug-1" aria-label="Permalink to “熱愛你的 bug”">​</a></h4><p>我在 Recurse Center 工作時會直白地歡迎挑戰，我就是這樣學會熱愛我的 bug 的。有時參與者會坐到我身邊説“唉，我覺得我遇到了個奇怪的 Python bug”，然後我會説“太棒了，我 <em>愛</em> 奇怪的 Python bug！” 首先，這百分之百是真的，但更重要的是，我這樣是在對參與者強調，找到讓自己覺得困難的事情是一種成就，而他們做到了這一點，這是件好事。</p><p>像我之前説過的，在 Recurse Center 沒有截止日期也沒有作業，所以這種態度沒有任何成本。我會説，“你現在可以花一整天去在 Flask 裏找出這個奇怪的 bug 了，多令人興奮啊！”在 Dropbox 和之後的 Pilot，我們有產品需要發佈，有截止日期，還有用户，於是我並不總是對在奇怪的 bug 上花一整天而感到興奮。所以我對有截止日期的現實也是感同身受。但是如果我有 bug 需要解決，我就必須得去解決它，而抱怨它的存在並不會幫助我之後更快地解決它。我覺得就算在截止日期臨近的時候，你也依然可以保持這樣的心態。</p><p>如果你熱愛你的 bug，你可以在解決困難問題時獲得更多樂趣。你可以擔心得更少而更加專注，並且從中學到更多。最後，你可以和你的朋友和同事分享你的 bug，這將會同時幫助你自己和你的隊友們。</p><h3 id="鳴謝" tabindex="-1">鳴謝！ <a class="header-anchor" href="#鳴謝" aria-label="Permalink to “鳴謝！”">​</a></h3><p>在此向給我的演講提出反饋以及給我的演講提供其他幫助的人士表示感謝：</p><ul><li>Sasha Laundy</li><li>Amy Hanlon</li><li>Julia Evans</li><li>Julian Cooper</li><li>Raphael Passini Diniz 以及其他的 Python Brasil 組織團隊成員</li></ul><hr>',15)),p("p",null,[a[19]||(a[19]=s("via: ",-1)),e(n,{href:"http://akaptur.com/blog/2017/11/12/love-your-bugs/"},{default:l(()=>[...a[18]||(a[18]=[s("http://akaptur.com/blog/2017/11/12/love-your-bugs/",-1)])]),_:1})]),p("p",null,[a[23]||(a[23]=s("作者：",-1)),e(n,{href:"http://akaptur.com/about/"},{default:l(()=>[...a[20]||(a[20]=[s("Allison Kaptur",-1)])]),_:1}),a[24]||(a[24]=s(" 譯者：",-1)),e(n,{href:"https://github.com/yixunx"},{default:l(()=>[...a[21]||(a[21]=[s("yixunx",-1)])]),_:1}),a[25]||(a[25]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...a[22]||(a[22]=[s("wxy",-1)])]),_:1})]),p("p",null,[a[28]||(a[28]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[26]||(a[26]=[s("LCTT",-1)])]),_:1}),a[29]||(a[29]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...a[27]||(a[27]=[s("Linux中國",-1)])]),_:1}),a[30]||(a[30]=s(" 榮譽推出",-1))])])}const C=t(u,[["render",g]]);export{y as __pageData,C as default};
